-- copy-pilot-2026-10-06: read-only preflight of paste-2026-10-06.sql. Expect 0 rows; a row names a statement whose
-- guard does not match exactly one card, or whose new text does not decode to the intended bytes.
select t.n, t.slug, t.field, t.rows_matched, t.text_ok
from (values
  (1, 'milk-and-madu-beach-road', 'why_its_here', (select count(*)::int from venues where slug = 'milk-and-madu-beach-road' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0748e95f6c49ce02e6ab5ea70f8bf6e5'), md5('An all-day cafe on Batu Bolong beach road, part of the Milk & Madu group. The room is spacious and shaded by palms, with a kids'' play area, and the kitchen does brunch classics and lava-stone pizzas.') = '533a7e3c1ec5fca748d98eed89478b45'),
  (2, 'milk-and-madu-beach-road', 'best_for', (select count(*)::int from venues where slug = 'milk-and-madu-beach-road' and status = 'active' and publication_status = 'published' and md5(best_for) = '4e8da344161f8a5beff5f8e243316522'), md5('Families with young children and groups, from brunch to an early dinner or the daily sunset session') = '97388b1facc43129d8d45070ac0823cd'),
  (3, 'milk-and-madu-beach-road', 'not_for', (select count(*)::int from venues where slug = 'milk-and-madu-beach-road' and status = 'active' and publication_status = 'published' and md5(not_for) = '1d5f69119a6d94bde19873fb553be246'), md5('Couples after a quiet, intimate dinner') = '6f8370c0c067f62cc0c208b666604b47'),
  (4, 'atlas-beach-club', 'why_its_here', (select count(*)::int from venues where slug = 'atlas-beach-club' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '12f27138f329e140c020ea56c69f69ac'), md5('A large beachfront complex on Jl. Pantai Berawa. It runs four venues on one site: a beach club, the Super Club, a wellness club and a padel club. Its own website calls it the world''s biggest beach club; we have not checked that. You enter on a day pass, and daybeds and sofas are booked separately.') = '8036b2828f79d88a5db37200a6d9d0a3'),
  (5, 'atlas-beach-club', 'best_for', (select count(*)::int from venues where slug = 'atlas-beach-club' and status = 'active' and publication_status = 'published' and md5(best_for) = 'c2b9fb07d31251c49b835e07806e7780'), md5('A big, lively day out with a group, or sunset drinks in a party crowd') = '9445629366aca7bd813b8b8478fa4744'),
  (6, 'atlas-beach-club', 'not_for', (select count(*)::int from venues where slug = 'atlas-beach-club' and status = 'active' and publication_status = 'published' and md5(not_for) = 'a18dfbbd8fe037b56362a4377cbb89aa'), md5('A small, quiet or intimate evening') = '33e8a3108cd7c45d25baee0ee80a0563'),
  (7, 'nook-umalas', 'why_its_here', (select count(*)::int from venues where slug = 'nook-umalas' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'e2e1a38e58ff30a1026acca87281f9c3'), md5(U&'An open-air caf\00E9 and restaurant beside the Umalas rice fields, open 8am to 11pm. The menu runs Western and Indonesian all day, from breakfast to late, with vegetarian, vegan and gluten-free dishes. Seminyak and its bustle are a short hop away.') = 'ec4b2161ba16bfbad76f20b2c62593e7'),
  (8, 'nook-umalas', 'best_for', (select count(*)::int from venues where slug = 'nook-umalas' and status = 'active' and publication_status = 'published' and md5(best_for) = '32f7572bbbe2c6b0ee8290e4d962d6b0'), md5('A calm breakfast or brunch looking at rice fields, for couples or a group staying off the strip') = 'ebd9eaa31cdd42271ae7ac404f75056d'),
  (9, 'nook-umalas', 'not_for', (select count(*)::int from venues where slug = 'nook-umalas' and status = 'active' and publication_status = 'published' and md5(not_for) = '4a789dd1f73cf3e55941eb6130056d34'), md5('Polished fine dining, a beachfront setting or a night out') = '509f2a8de761721ece7b604781937e48'),
  (10, 'ji-restaurant-bali', 'why_its_here', (select count(*)::int from venues where slug = 'ji-restaurant-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0bf9ed9f370f2067913711e0165406e1'), md5('Japanese-contemporary dining at Hotel Tugu, right on Batu Bolong beach. The room is a reconstructed antique temple, and the terrace looks straight at the ocean. Sushi, Asian-fusion plates and cocktails.') = 'dda183a1818aa2e9cd7a1683cadc13ce'),
  (11, 'ji-restaurant-bali', 'best_for', (select count(*)::int from venues where slug = 'ji-restaurant-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = '1a8cf6414afcec9522f16b9e15de924f'), md5('A sunset dinner with a view, a date, or a special occasion by the sea') = '3938cdc40fb0d23fbacb8120fd2e7f16'),
  (12, 'sensorium-bali', 'why_its_here', (select count(*)::int from venues where slug = 'sensorium-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '0a6e6c780c7f8561379decc387a9ba68'), md5('A daytime cafe on Jl. Pantai Batu Mejan run by a chef trained in Australian fine dining. The food is Australian cafe cooking with Japanese flavours, and the room is minimalist.') = 'd2884b2f41c3fb7c8f8b67f61346af2c'),
  (13, 'sensorium-bali', 'best_for', (select count(*)::int from venues where slug = 'sensorium-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'cbb896544163a18d1fb61d5e8530585c'), md5('Brunch or lunch in a calm, design-led room, or a daytime stop with a laptop') = 'ab062fc45e7b7bd4e3369c3015d5f9dd'),
  (14, 'sensorium-bali', 'not_for', (select count(*)::int from venues where slug = 'sensorium-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '49dab13721423d38a8822fdd90ce0da6'), md5(U&'Dinner or late-night plans \2014 it keeps daytime hours only') = '357f6a56af536557bdda41c4e83e6f7c'),
  (15, 'fair-warung-bale', 'why_its_here', (select count(*)::int from venues where slug = 'fair-warung-bale' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'f1a315b9047d954ebf605e83e6d26ccc'), md5('A ten-table warung on Jalan Sriwedari in Taman Kaja, run by the Fair Future Foundation and Bali Sari Foundation. What you pay here funds free medical consultations for local people. The menu is Indonesian, Asian-fusion and vegetarian, every day.') = 'ad95da40f1ebb8a69909baaaaa2d283b'),
  (16, 'fair-warung-bale', 'best_for', (select count(*)::int from venues where slug = 'fair-warung-bale' and status = 'active' and publication_status = 'published' and md5(best_for) = '0999d51d72296b3dbdf1ddcf2a9e53ff'), md5('A casual lunch or early dinner that also funds free medical consultations locally') = 'f7c407de1b42393798fd68a53576664b'),
  (17, 'fair-warung-bale', 'not_for', (select count(*)::int from venues where slug = 'fair-warung-bale' and status = 'active' and publication_status = 'published' and md5(not_for) = 'f1197410a8e33d56e3fef62564a2896c'), md5('Upscale dining or a sunset view. It is a simple ten-table warung') = '33129efb36327d67ff923c940ba93806'),
  (18, 'warung-mendez', 'why_its_here', (select count(*)::int from venues where slug = 'warung-mendez' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '6df999f0def9cabe28c2f1aed3ea210f'), md5('A small warung in Penestanan village, northwest of central Ubud, with an all-women kitchen team. The cooking is Indonesian and Javanese, made without MSG and with little plastic.') = '11bb073c20dc12f9eca30d486e06362e'),
  (19, 'warung-mendez', 'best_for', (select count(*)::int from venues where slug = 'warung-mendez' and status = 'active' and publication_status = 'published' and md5(best_for) = 'b4b71123fa51b580b3e13921c93e1dd8'), md5('A quiet, home-style Indonesian meal away from the main Ubud strip') = '1033be3b0e4e6d050f79a8807ba72e32'),
  (20, 'warung-mendez', 'not_for', (select count(*)::int from venues where slug = 'warung-mendez' and status = 'active' and publication_status = 'published' and md5(not_for) = '190ee771db96a917712c7ea6293b38e6'), md5('A quick stop in the centre of town; Penestanan takes finding') = 'e8c0645b2c9436da68b86bb530a56625'),
  (21, 'wulan-vegetarian-warung', 'why_its_here', (select count(*)::int from venues where slug = 'wulan-vegetarian-warung' and status = 'active' and publication_status = 'published' and md5(why_its_here) = 'cf75ef29151bd213f5d6d4aa63e36046'), md5('A small all-vegan warung in Peliatan, Ubud, with floor-cushion seating and cash only. The menu is Indonesian: nasi goreng, tempeh, smoothies and vegan sweets, at very low prices.') = 'd601aabd0e72c0943d4a8635e9edf338'),
  (22, 'wulan-vegetarian-warung', 'best_for', (select count(*)::int from venues where slug = 'wulan-vegetarian-warung' and status = 'active' and publication_status = 'published' and md5(best_for) = '885d4df1a2a9ab96d634cd12df147c53'), md5('Vegan or vegetarian travellers on a budget who want simple Indonesian food') = '17b28a5d1d042088b02088ab9e81d191'),
  (23, 'wulan-vegetarian-warung', 'not_for', (select count(*)::int from venues where slug = 'wulan-vegetarian-warung' and status = 'active' and publication_status = 'published' and md5(not_for) = '67f309837e73b7f82386a7b31f2be1b7'), md5('Card payments or a table and chairs: it is cash only, with floor cushions') = '0f8eb7748855dec0c8df6329490f7f78'),
  (24, 'bali-buda-ubud', 'why_its_here', (select count(*)::int from venues where slug = 'bali-buda-ubud' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '38049551a7708301a15f3942208a616d'), md5('An organic grocery and bakery with an all-day restaurant attached, in Ubud since 1994. The kitchen covers raw vegan, Italian and traditional Indonesian dishes.') = '817a878d28270159e3ac4b6fae296ddf'),
  (25, 'bali-buda-ubud', 'best_for', (select count(*)::int from venues where slug = 'bali-buda-ubud' and status = 'active' and publication_status = 'published' and md5(best_for) = '32f4583669479f3acb839c7cfb1743c2'), md5('A long stay or a mixed group that needs one big menu with vegetarian, vegan and gluten-free choices') = '89b49ea9aa50522d40eced3b914363e1'),
  (26, 'bali-buda-ubud', 'not_for', (select count(*)::int from venues where slug = 'bali-buda-ubud' and status = 'active' and publication_status = 'published' and md5(not_for) = '4b732763b0cf319314c13655847fc21f'), md5('A special occasion or an intimate dinner, because it is a casual health-food restaurant and shop') = 'f02a3e708e5b5e67fbc171b570e53488'),
  (27, 'kilig-bali', 'why_its_here', (select count(*)::int from venues where slug = 'kilig-bali' and status = 'active' and publication_status = 'published' and md5(why_its_here) = '9f182db884153bdd08fb69ddb7a64eaa'), md5('A Filipino warung in Peliatan, in a bamboo hut looking over rice fields. The cooking is home-style Filipino comfort food, in an area where the menus are otherwise Balinese and Western.') = 'e9f5ecd96ef951554c40412cecef61d4'),
  (28, 'kilig-bali', 'best_for', (select count(*)::int from venues where slug = 'kilig-bali' and status = 'active' and publication_status = 'published' and md5(best_for) = 'da51a99e56e173bc2a79c1d5de013e08'), md5('Filipino comfort food at a shared table, or a calm family dinner looking over rice fields') = 'c5e8e502928b40d1a820d5e57535bfb8'),
  (29, 'kilig-bali', 'not_for', (select count(*)::int from venues where slug = 'kilig-bali' and status = 'active' and publication_status = 'published' and md5(not_for) = '79aa53b8e3ba27169e089e4edaf6c62c'), md5('A quick stop from central Ubud, or anyone avoiding rich, pork-heavy dishes') = 'c0219f9b2f75a81741a1adbf3df1a8d1')
) as t(n, slug, field, rows_matched, text_ok)
where t.rows_matched <> 1 or not t.text_ok
order by t.n;
